"""ANSI TCAP dissector (packet-ansi_tcap.c, generated by asn2wrs from
epan/dissectors/asn1/ansi_tcap/).

ANSI TCAP is carried the way it is in an SS7 over IP network:

  Ethernet / IPv4 / SCTP (PPID 3) / M3UA DATA / SCCP UDT or LUDT (ANSI) /
  ANSI TCAP

Decode with -o mtp3.standard:ANSI (cfg/profiles/ansi_tcap does that).  The
SSNs are in the 5-14 range ANSI MAP registers with TCAP, so SCCP hands
every package to TCAP, which passes the PRIVATE-class package types to
ANSI TCAP.  ANSI TCAP then hands the component parameters to ANSI MAP
(private operation family 9), AIN (private 0x6xxx), the national opcode
table (LNP query 0x0301/0x0401) or decodes national parameters itself.

Network elements (ANSI point codes):
  MSC/SSP  10.0.0.1  1-1-1  SSN 8      HLR/SCP 10.0.0.2  2-2-2  SSN 6
  STP/relay 10.0.0.22 22-22-22 SSN 8   MSC-B   10.0.0.21 21-21-21 SSN 8

The cases of "ANSI TCAP: Stop handing components over before the layer
limit" are carried over SCCP: the ones that decode without a malformed
packet in the main capture, the others in the malformed capture. Their TCAP
octets are rebuilt here and checked against the Exported PDU captures
ansi_tcap_*.pcap next to this script.

Usage: mkansi_tcap.py [<output directory>]

Writes ansi_tcap-coverage.pcap and ansi_tcap-coverage-malformed.pcap. Every
packet is built here; nothing comes from a real network.
"""

import os
import sys

sys.path.insert(1, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'shared'))















import struct

from capgen import eth, ipv4, read_pcap, sctp, sctp_data, write_pcap  # noqa: E402
from repro import reproducer_dir

# ---------------------------------------------------------------- BER

UNI, APP, CON, PRI = 0, 1, 2, 3


def ber_tag(cls, constructed, tag):
    first = (cls << 6) | (0x20 if constructed else 0)
    if tag < 31:
        return bytes([first | tag])
    out = [tag & 0x7f]
    tag >>= 7
    while tag:
        out.insert(0, 0x80 | (tag & 0x7f))
        tag >>= 7
    return bytes([first | 0x1f] + out)


def ber_len(n):
    if n < 0x80:
        return bytes([n])
    b = n.to_bytes((n.bit_length() + 7) // 8, 'big')
    return bytes([0x80 | len(b)]) + b


def tlv(cls, constructed, tag, content):
    return ber_tag(cls, constructed, tag) + ber_len(len(content)) + content


def ber_int(v):
    n = 1
    while True:
        try:
            return v.to_bytes(n, 'big', signed=True)
        except OverflowError:
            n += 1


def oid_body(dotted):
    a = [int(x) for x in dotted.split('.')]
    out = bytes([a[0] * 40 + a[1]])
    for v in a[2:]:
        enc = [v & 0x7f]
        v >>= 7
        while v:
            enc.append(0x80 | (v & 0x7f))
            v >>= 7
        out += bytes(reversed(enc))
    return out


def bcd(digits):
    if len(digits) % 2:
        digits += 'F'
    return bytes(int(digits[i + 1], 16) << 4 | int(digits[i], 16) for i in range(0, len(digits), 2))


class Bits:
    def __init__(self):
        self.b = []

    def put(self, val, n):
        for i in range(n - 1, -1, -1):
            self.b.append((val >> i) & 1)

    def bytes(self):
        b = self.b + [0] * ((-len(self.b)) % 8)
        return bytes(int(''.join(map(str, b[i:i + 8])), 2) for i in range(0, len(b), 8))


# ---------------------------------------------------------------- ANSI TCAP

UNIDIR, QUERY_PERM, QUERY_NOPERM, RESPONSE, CONV_PERM, CONV_NOPERM, ABORT = 1, 2, 3, 4, 5, 6, 22


def component_ids(*ids):
    return tlv(PRI, False, 15, bytes(ids))


def opcode_private(code):
    return tlv(PRI, False, 17, struct.pack('!H', code))


def opcode_national(code):
    return tlv(PRI, False, 16, struct.pack('!H', code))


def invoke(ids, opcode, param, last=True):
    """ids: tuple of 0-2 component IDs, or None to leave componentIDs out;
    opcode: encoded OperationCode."""
    body = b'' if ids is None else component_ids(*ids)
    body += opcode
    if param is not None:
        body += param
    return tlv(PRI, True, 9 if last else 13, body)


def return_result(inv_id, param, last=True):
    body = component_ids(inv_id)
    if param is not None:
        body += param
    return tlv(PRI, True, 10 if last else 14, body)


def return_error(inv_id, errcode, param):
    body = component_ids(inv_id) + errcode
    if param is not None:
        body += param
    return tlv(PRI, True, 11, body)


def error_private(code):
    return tlv(PRI, False, 20, bytes([code]))


def error_national(code):
    # [PRIVATE 19] is EXPLICIT: an INTEGER inside
    return tlv(PRI, True, 19, tlv(UNI, False, 2, ber_int(code)))


def reject(ids, problem, param_tag=16):
    body = component_ids(*ids) + tlv(PRI, False, 21, struct.pack('!H', problem))
    body += tlv(PRI, True, param_tag, b'')
    return tlv(PRI, True, 12, body)


def comp_seq(components):
    return tlv(PRI, True, 8, b''.join(components))


def package(ptype, tid, components, dialogue=None):
    body = tlv(PRI, False, 7, tid)
    if dialogue is not None:
        body += dialogue
    if components is not None:
        body += comp_seq(components)
    return tlv(PRI, True, ptype, body)


def abort(tid, cause, dialogue=None):
    body = tlv(PRI, False, 7, tid)
    if dialogue is not None:
        body += dialogue
    return tlv(PRI, True, ABORT, body + cause)


def p_abort(cause):
    return tlv(PRI, False, 23, ber_int(cause))


def external(oid, inner):
    """EXTERNAL with a direct-reference and a single-ASN1-type encoding."""
    return tlv(UNI, True, 8, tlv(UNI, False, 6, oid_body(oid)) + tlv(CON, True, 0, inner))


def user_abort(oid, inner):
    # [PRIVATE 24] EXPLICIT EXTERNAL
    return tlv(PRI, True, 24, external(oid, inner))


def dialogue(version=None, app_int=None, app_oid=None, user_info=None,
             sec_int=None, sec_oid=None, conf=None):
    body = b''
    if version is not None:
        body += tlv(PRI, False, 26, bytes([version]))
    if app_int is not None:
        body += tlv(PRI, False, 27, ber_int(app_int))
    if app_oid is not None:
        body += tlv(PRI, False, 28, oid_body(app_oid))
    if user_info is not None:
        body += tlv(PRI, True, 29, b''.join(user_info))
    if sec_int is not None:
        body += tlv(CON, False, 0, ber_int(sec_int))
    if sec_oid is not None:
        body += tlv(CON, False, 1, oid_body(sec_oid))
    if conf is not None:
        body += tlv(CON, True, 2, conf)
    return tlv(PRI, True, 25, body)


# ---------------------------------------------------------------- payloads

def pset(*params):
    return tlv(PRI, True, 18, b''.join(params))


def is637_bearer(text='Hello from ANSI TCAP'):
    mi = Bits()
    mi.put(1, 4)
    mi.put(0x1234, 16)
    mi.put(0, 1)
    mi.put(0, 3)
    msg_id = bytes([0x00, 0x03]) + mi.bytes()
    ud = Bits()
    ud.put(2, 5)
    ud.put(len(text), 8)
    for c in text.encode():
        ud.put(c, 7)
    ud = ud.bytes()
    return msg_id + bytes([0x01, len(ud)]) + ud


# ANSI MAP SMSDeliveryPointToPoint (private 0x0935): SMS_BearerData [105]
# and SMS_TeleserviceIdentifier [116] (CDMA Cellular Messaging, 4098)
SMSDPP = 0x0900 | 53
SMSDPP_ARG = pset(tlv(CON, False, 105, is637_bearer()), tlv(CON, False, 116, struct.pack('!H', 4098)))
SMSDPP_RES = pset()
# ANSI MAP the reproducer uses (teleservice only: a BER missing-field warning)
REPRO_TELEID = tlv(CON, False, 116, struct.pack('>H', 4098))
ESN = tlv(CON, False, 9, bytes([0x9f, 0x12, 0x34, 0x56]))
# SMSNotification (0x0936): the ESN is its only mandatory parameter
SMSNOT = 0x0900 | 54
SMSNOT_ARG = pset(ESN)
# RegistrationNotification (0x090d): ESN, MSCID, QualificationInformationCode,
# SystemMyTypeCode
REGNOT = 0x0900 | 13
REGNOT_ARG = pset(ESN, tlv(CON, False, 21, bytes([0x00, 0x12, 0x01])), tlv(CON, False, 17, b'\x03'),
                  tlv(CON, False, 22, b'\x05'))
# The SMS operation with empty bearer data: no hand-off to IS-637, so each
# component adds only the ANSI MAP layer (the many-components packages)
SMSDPP_ARG_NOBD = pset(tlv(CON, False, 105, b''), REPRO_TELEID)
# A smaller activityTest argument (no extension parameter)
AIN_ACTIVITY_ARG_SMALL = tlv(UNI, True, 16, bytes.fromhex('9f81230411223344'))


def lnp_digits(tag, tod, digits):
    return tlv(CON, False, tag, bytes([tod, 0x00, 0x21, len(digits)]) + bcd(digits))


# LNP query (packet-lnpdqp.c): Provide Instruction Start (national 0x0301,
# H bit set) with the dialled number, the calling party and the OLI;
# Connection Control Connect (0x0401) with the routing number and the
# billing indicators.
LNP_PI = 0x8301
LNP_PI_ARG = pset(tlv(CON, True, 10, lnp_digits(4, 6, '2015550123')), lnp_digits(4, 2, '7325550199'),
                  tlv(PRI, False, 69, b'\x00'))
LNP_CC = 0x0401
LNP_CC_ARG = pset(lnp_digits(4, 4, '2015559999'), tlv(PRI, False, 65, b'\x00\x01\x02\x03'))


# ---------------------------------------------------------------- national parameters
# parameter_type() reads: identifier (1 octet, or 2 when the low nibble of
# the first is 0xF), one octet it skips, the length, then a value of the
# size each case expects; dissect after the value skips one more octet.
# These helpers produce exactly that layout.

def nparam(ident, value, length=None):
    ib = ident.to_bytes(2 if ident > 0xff else 1, 'big')
    if length is None:
        length = len(value)
    return ib + b'\x00' + bytes([length]) + value + b'\x00'


def national_set(*params):
    content = b''.join(params)
    return bytes([0xf2]) + ber_len(len(content)) + content


NAT_PARAMS = [
    # Timestamp: 26/10/27 12:30, difference -5, local 07:30
    nparam(0x17, bytes([26, 10, 27, 12, 30, 0xfb, 7, 30])),
    nparam(0x81, bytes([0x03, 0x05, 0x0a])),                    # ACG indicators
    nparam(0x82, bytes([0x05])),                                # standard announcement
    nparam(0x83, bytes([0x03, 0x11, 0x22, 0x33])),              # customized announcement
    nparam(0x84, bytes([0x06, 0x01, 0x21, 0x04, 0x02, 0x00, 0x01, 0x05])),  # digits
    nparam(0x85, bytes([0x01])),                                # standard user error code
    nparam(0x86, b'', 2),                                       # problem data (no decoder, nothing read)
    nparam(0x87, bytes([0x42])),                                # SCCP calling party address
    nparam(0x88, bytes([0x07])),                                # transaction ID
    nparam(0x89, bytes([0xe2])),                                # package type
    nparam(0x8a, bytes([0x01, 0x05, 0x01, 0x02, 0x11, 0x02, 0x10, 0x55, 0x05, 0x21,
                        0x02, 0x05, 0x01, 0x00, 0x11, 0x37, 0x52, 0x55, 0x09, 0x91])),
    nparam(0xaa, bytes([0x01, 0x05, 0x01, 0x00, 0x11, 0x02, 0x10, 0x55, 0x05, 0x21,
                        0x02, 0x05, 0x01, 0x02, 0x11, 0x37, 0x52, 0x55, 0x09, 0x91])),
    nparam(0x8b, bytes([0x01])),                                # busy/idle status
    nparam(0x8c, bytes([0x5a])),                                # call forwarding status
    nparam(0x8d, bytes([0x02])),                                # originating restrictions
    nparam(0x8e, bytes([0x04])),                                # terminating restrictions
    # DN to line service type mapping (0x8f): its low nibble is 0xF, so
    # parameter_type() reads a 2-octet identifier 0x8fxx and never reaches
    # case 0x8f; shown as the unknown parameter 0x8f00
    nparam(0x8f00, b'', 1),
    nparam(0x90, bytes([0x01, 0x02, 0x03])),                    # duration
    nparam(0x91, bytes([0x8b])),                                # returned data
    nparam(0x92, bytes([0x80, 0x90, 0xa2, 0x00, 0x01, 0x02])),  # bearer capability requested
    nparam(0x93, bytes([0x02])),                                # bearer capability supported
    nparam(0x94, bytes([0x33])),                                # reference ID
    nparam(0x95, bytes([0x5f, 0x00, 0x12, 0x34, 0x00, 0x56, 0x07])),  # business group
    nparam(0x96, bytes([0x02, 0x01, 0x02])),                    # signalling networks ID
    nparam(0x97, bytes([0x05, 0x21]) + b'ALICE'),               # generic name
    nparam(0x98, bytes([0x21])),                                # message waiting indicator
    nparam(0x99, bytes([0x45])),                                # look ahead for busy
    nparam(0x9a, bytes([0x34, 0x12])),                          # CIC
    nparam(0x9b, bytes([0x04, 0x12, 0x34, 0x00, 0x00, 0x01])),  # precedence
    nparam(0x9c, bytes([0x00, 0x00, 0x2a, 0x01, 0x01, 0x01])),  # call reference identifier
    nparam(0x9d, bytes([0x01])),                                # authorization
    nparam(0x9e, bytes([0x01, 0x02, 0xaa, 0xbb, 0x02, 0x03, 0x01, 0x02, 0x03])),  # integrity
    nparam(0x9f1f, bytes([0x02, 0x00, 0x07])),                  # sequence number
    nparam(0x7f20, bytes([0x01, 0x03])),                        # number of messages
    nparam(0x7f21, bytes([0x05]) + b'HELLO'),                   # display text
    nparam(0x7f22, bytes([0x01, 0x01, 0x05, 0x02, 0x02, 0xca, 0xfe])),  # key exchange
    nparam(0x7f23, b'', 3),                                     # SCCP called party address (not decoded)
    nparam(0xa5, b'', 2),                                       # unknown identifier
    nparam(0x82, b''),                                          # length 0: "asking to be returned"
    nparam(0x7f21, b''),                                        # 2-octet identifier, length 0
]


# ---------------------------------------------------------------- SS7 over IP

def node(i, ssn):
    return {'ip': bytes([10, 0, 0, i]), 'mac': bytes([2, 0, 0, 0, 0, i]), 'pc': (i, i, i),
            'port': 2904 + i, 'vtag': 0x54000000 + i, 'ssn': ssn}


MSC = node(1, 8)
HLR = node(2, 6)
MSCB = node(21, 8)
RELAY = node(22, 8)
tsn = {}


def ansi_pc(network, cluster, member):
    return network << 16 | cluster << 8 | member


def sccp_addr(n):
    return bytes([0xc3, n['ssn'], n['pc'][2], n['pc'][1], n['pc'][0]])


def sccp_udt(src, dst, data):
    called = sccp_addr(dst)
    calling = sccp_addr(src)
    if len(data) <= 255:
        p1 = 3
        p2 = 2 + len(called) + 1
        p3 = 1 + len(called) + 1 + len(calling) + 1
        return (bytes([0x09, 0x00, p1, p2, p3]) + bytes([len(called)]) + called +
                bytes([len(calling)]) + calling + bytes([len(data)]) + data)
    # Long Unitdata: class 0, hop counter, four 2-octet pointers
    p1 = 7
    p2 = 6 + len(called)
    p3 = 5 + len(called) + len(calling)
    return (bytes([0x13, 0x00, 0x0f]) + struct.pack('<HHHH', p1, p2, p3, 0) +
            bytes([len(called)]) + called + bytes([len(calling)]) + calling +
            struct.pack('<H', len(data)) + data)


def m3ua_data(src, dst, sccp, sls):
    pd = struct.pack('!IIBBBB', ansi_pc(*src['pc']), ansi_pc(*dst['pc']), 3, 2, 0, sls) + sccp
    prm = struct.pack('!HH', 0x0210, 4 + len(pd)) + pd
    prm += b'\0' * (-len(prm) % 4)
    return struct.pack('!BBBBI', 1, 0, 1, 1, 8 + len(prm)) + prm


def sctp_packet(src, dst, payload):
    key = (src['ip'], dst['ip'])
    tsn[key] = tsn.get(key, 0) + 1
    chunk = sctp_data(payload, tsn[key], 3, ssn=tsn[key] & 0xffff)
    return sctp(chunk, src['port'], dst['port'], dst['vtag'])


def frame(src, dst, tcap, sls=0):
    pkt = sctp_packet(src, dst, m3ua_data(src, dst, sccp_udt(src, dst, tcap), sls))
    return eth(ipv4(pkt, 132, src=src['ip'], dst=dst['ip'], ident=0, flags_frag=0x4000), 0x0800,
               dst=dst['mac'], src=src['mac'])


def write_frames(path, frames):
    """frames: (bytes, note) pairs."""
    write_pcap(path, [fr for fr, _ in frames], ts=lambda i: (1792540800 + i, 0))


# ---------------------------------------------------------------- AIN components
# activityTest (private 26886) Invoke argument and ReturnResult, the octets
# of frame 1 of ../ain-coverage/ain-coverage.pcap (built from the AIN
# ASN.1 by mkain.py): ActivityTestArg with its extension parameter.

AIN_ACTIVITY_TEST = 0x6906
AIN_ACTIVITY_ARG = bytes.fromhex('30299f81230411223344bf541e0603550403131741494e2073796e74686574696320657874656e73696f6e')
AIN_ACTIVITY_RES = bytes.fromhex('30059f81240100')


# ---------------------------------------------------------------- reproducers
# The TCAP octets of the ansi_tcap_*.pcap captures (Exported PDU), rebuilt
# with the same functions.

def r_invoke(inv_id, op, params, last=True):
    body = tlv(PRI, 0, 15, bytes([inv_id & 0xff])) + tlv(PRI, 0, 17, struct.pack('>H', op))
    if params is not None:
        body += tlv(PRI, 1, 18, params)
    return tlv(PRI, 1, 9 if last else 13, body)


def r_invoke_national(inv_id, op, params, last=True):
    body = tlv(PRI, 0, 15, bytes([inv_id & 0xff])) + tlv(PRI, 0, 16, struct.pack('>H', op))
    if params is not None:
        body += params
    return tlv(PRI, 1, 9 if last else 13, body)


def r_return_result(inv_id, params, last=True):
    body = tlv(PRI, 0, 15, bytes([inv_id & 0xff]))
    if params is not None:
        body += tlv(PRI, 1, 18, params)
    return tlv(PRI, 1, 10 if last else 14, body)


def r_package(ptype, tid, comps):
    return tlv(PRI, 1, ptype, tlv(PRI, 0, 7, tid) + tlv(PRI, 1, 8, b''.join(comps)))


def reproducers():
    """name -> list of TCAP payloads."""
    r = {}
    teleid = REPRO_TELEID
    for name, n in (('many_components', 600), ('many_components_ok', 400)):
        comps = [r_invoke(i, 0x0900 | 53, teleid, last=(i == n - 1)) for i in range(n)]
        r[name] = [r_package(2, b'\x00\x00\x00\x01', comps)]
    comps = [r_invoke(i, 0x6101, b'', last=(i == 599)) for i in range(600)]
    r['many_components_ain'] = [r_package(2, b'\x00\x00\x00\x02', comps)]
    comps = [r_invoke_national(i, 0x8301, tlv(PRI, 1, 18, b''), last=(i == 599)) for i in range(600)]
    r['many_components_lnp'] = [r_package(2, b'\x00\x00\x00\x03', comps)]
    comps = [r_invoke(1, 0x0900 | 53, teleid, last=False),
             r_return_result(1, b'', last=False),
             r_invoke(2, 0x0900 | 13, b'', last=True)]
    r['same_frame_match'] = [r_package(4, b'\x00\x00\x00\x10', comps)]
    comps = [r_invoke(1, 0x0900 | 53, teleid)]
    r['tid_lengths'] = [r_package(2, tid, comps) for tid in (bytes(range(8)), bytes(300), bytes(256), b'\x01\x02\x03')]
    psets = [
        bytes([0xf2, 0xff]) + bytes([0x8a, 0x00, 0x05]) + b'\x01' * 8,
        bytes([0xf2, 0x10]) + bytes([0x8f, 0x8f, 0x00, 0xff]) + b'\x02',
        bytes([0xf2, 0x7f]) + (bytes([0x81, 0x00, 0x02, 0xff, 0xff]) * 30),
    ]
    r['national_params'] = [r_package(2, struct.pack('>I', 0x20 + i), [r_invoke_national(1, 0x8105, ps)])
                            for i, ps in enumerate(psets)]
    return r


def read_exported_pdus(path):
    """TCAP payloads of an Exported PDU (linktype 252) pcap."""
    out = []
    for rec in read_pcap(path):
        p = 0
        while p + 4 <= len(rec):
            t, ln = struct.unpack('!HH', rec[p:p + 4])
            p += 4 + ln
            if t == 0:
                break
        out.append(rec[p:])
    return out


# ---------------------------------------------------------------- captures

def build(repro_dir):
    clean = []
    malformed = []
    tid_n = [0x00a00000]

    def tid():
        tid_n[0] += 1
        return struct.pack('!I', tid_n[0])

    def add(caps, src, dst, tcap, note):
        caps.append((frame(src, dst, tcap, len(caps) & 0x0f), note))

    def c(src, dst, tcap, note):
        add(clean, src, dst, tcap, note)

    def m(src, dst, tcap, note):
        add(malformed, src, dst, tcap, note)

    def sms(i=1, last=True):
        return invoke((i,), opcode_private(SMSDPP), SMSDPP_ARG, last)

    # ---- package types (ANSI MAP SMSDeliveryPointToPoint, IS-637 bearer data)
    c(MSC, HLR, package(UNIDIR, b'', [sms()]), 'unidirectional, empty TID, Invoke (not saved: no TID)')
    c(HLR, MSC, package(UNIDIR, b'', [return_result(1, SMSDPP_RES)]), 'unidirectional, ReturnResult without TID (not looked up)')
    t = tid()
    c(MSC, HLR, package(QUERY_PERM, t, [sms()]), 'queryWithPerm Invoke')
    c(HLR, MSC, package(RESPONSE, t, [return_result(1, SMSDPP_RES)]), 'response ReturnResult (matched)')
    t = tid()
    c(MSC, HLR, package(QUERY_NOPERM, t, [sms()]), 'queryWithoutPerm Invoke')
    c(HLR, MSC, package(RESPONSE, t, [return_result(1, SMSDPP_RES)]), 'response ReturnResult (matched)')
    to, tr = tid(), tid()
    c(MSC, HLR, package(CONV_PERM, to + tr, [sms(1, False), invoke((2,), opcode_private(SMSNOT), SMSNOT_ARG)]),
      'conversationWithPerm, 8-octet TID, InvokeNotLast + InvokeLast')
    c(HLR, MSC, package(CONV_NOPERM, tr + to, [return_result(1, SMSDPP_RES, False), return_result(2, None)]),
      'conversationWithoutPerm, 8-octet TID, ReturnResultNotLast + ReturnResultLast without parameter; not matched: the last 4 octets of the reversed TID are the originating ID')
    c(HLR, MSC, package(RESPONSE, tid(), None), 'response without component portion')
    c(MSC, HLR, package(QUERY_PERM, tid(), None, dialogue(version=4)), 'queryWithPerm, dialogue portion only')

    # ---- transaction ID lengths
    for tl in (1, 2, 3, 8, 255):
        t = bytes((0xb0 + tl + i) & 0xff for i in range(tl))
        c(MSC, HLR, package(QUERY_PERM, t, [sms()]), 'queryWithPerm, %d-octet TID' % tl)
        c(HLR, MSC, package(RESPONSE, t, [return_result(1, SMSDPP_RES)]), 'response, %d-octet TID (matched)' % tl)
    t260 = bytes([0xc1, 0xc2, 0xc3, 0xc4]) + bytes((i * 7) & 0xff for i in range(256))
    c(MSC, HLR, package(QUERY_PERM, t260, [invoke((1,), opcode_national(0x0101), national_set(*NAT_PARAMS[:3]))]),
      'queryWithPerm, 260-octet TID, national Invoke')
    other = t260[:4] + bytes(256)
    c(HLR, MSC, package(RESPONSE, other, [return_result(1, national_set(NAT_PARAMS[5]))]),
      'response, 260-octet TID, same first 4 octets: not matched')
    c(HLR, MSC, package(RESPONSE, t260, [return_result(1, national_set(NAT_PARAMS[5]))]),
      'response, the same 260-octet TID: matched')

    # ---- dialogue portion
    ext = external('1.2.840.10013.3.4.1', tlv(UNI, False, 4, b'user data'))
    c(MSC, HLR, package(QUERY_PERM, tid(), [sms()],
                        dialogue(version=4, app_int=7, user_info=[ext, ext], sec_int=3,
                                 conf=tlv(CON, False, 0, b'\x05'))),
      'dialogue: version, integer application context, user information (2), integer security, integer confidentiality')
    c(MSC, HLR, package(QUERY_PERM, tid(), [sms()],
                        dialogue(app_oid='1.2.840.10013.2.1', sec_oid='1.2.840.10013.5.1',
                                 conf=tlv(CON, False, 1, oid_body('1.2.840.10013.6.2')))),
      'dialogue: OID application context, OID security, OID confidentiality')
    c(MSC, HLR, package(CONV_PERM, tid() + tid(), [sms()], dialogue(conf=b'')),
      'dialogue: empty confidentiality')
    c(MSC, HLR, package(UNIDIR, b'', [sms()], dialogue(version=1, app_int=300)),
      'unidirectional with dialogue portion')

    # ---- abort
    for cause in range(1, 11):
        c(HLR, MSC, abort(tid(), p_abort(cause)), 'abort, P-abort cause %d' % cause)
    c(HLR, MSC, abort(tid(), p_abort(42)), 'abort, unknown P-abort cause')
    c(HLR, MSC, abort(tid(), user_abort('1.2.840.10013.3.4.2', tlv(UNI, False, 2, b'\x01'))),
      'abort, user abort information (EXTERNAL)')
    c(HLR, MSC, abort(tid(), p_abort(6), dialogue(version=4, app_oid='1.2.840.10013.2.1')),
      'abort with dialogue portion')

    # ---- return error and reject
    t = tid()
    c(MSC, HLR, package(QUERY_PERM, t, [sms()]), 'Invoke for the ReturnErrors')
    for code in range(129, 141):
        c(HLR, MSC, package(RESPONSE, t, [return_error(1, error_private(code), pset())]),
          'ReturnError, private error code %d, parameter (to ANSI MAP)' % code)
    c(HLR, MSC, package(RESPONSE, t, [return_error(1, error_private(200), None)]),
      'ReturnError, unknown private code, no parameter')
    t = tid()
    c(MSC, HLR, package(QUERY_PERM, t, [invoke((1,), opcode_national(0x0101), national_set(NAT_PARAMS[1]))]),
      'national Invoke for the ReturnError')
    c(HLR, MSC, package(RESPONSE, t, [return_error(1, error_national(1), national_set(NAT_PARAMS[5]))]),
      'ReturnError, national error code, national parameters (matched)')
    c(HLR, MSC, package(RESPONSE, t, [return_error(1, error_national(-3), None)]),
      'ReturnError, negative national error code, no parameter')
    problems = [257, 258, 259, 260, 513, 514, 515, 516, 769, 770, 771,
                1025, 1026, 1027, 1028, 1029, 1281, 1282, 1283, 1284, 1285, 1286]
    rej = [reject((1,), p, 16 if i % 2 == 0 else 18) for i, p in enumerate(problems)]
    c(HLR, MSC, package(RESPONSE, tid(), rej), 'Reject with every problem code, paramSequence and paramSet')
    c(HLR, MSC, package(RESPONSE, tid(), [reject((), 999, 16)]), 'Reject, no component ID, unknown problem')

    # ---- component IDs
    t = tid()
    c(MSC, HLR, package(CONV_PERM, t + t, [invoke((3, 1), opcode_private(SMSDPP), SMSDPP_ARG),
                                           invoke((), opcode_private(SMSDPP), SMSDPP_ARG),
                                           invoke(None, opcode_private(SMSDPP), SMSDPP_ARG)]),
      'Invokes with invoke and correlation ID, with an empty and without componentIDs')

    # ---- operation codes: national families and specifiers
    specs = [(0, 0), (1, 1), (1, 2), (1, 3), (2, 1), (2, 2), (3, 1), (3, 2), (3, 3),
             (4, 1), (4, 2), (4, 3), (4, 4), (4, 5), (5, 1), (6, 1), (7, 1), (8, 1),
             (9, 1), (10, 1), (0x7e, 1), (0x7f, 1), (0x20, 1)]
    for fam, spec in specs:
        for h in (0, 0x8000):
            if fam in (3, 4) and spec in (1,) and h:
                continue    # registered LNP opcodes, below
            code = h | fam << 8 | spec
            if code & 0x7fff in (LNP_PI & 0x7fff, LNP_CC):
                continue
            c(MSC, HLR, package(QUERY_PERM, tid(), [invoke((1,), opcode_national(code), national_set(NAT_PARAMS[2]))]),
              'national opcode 0x%04x (family %d, specifier %d), not registered' % (code, fam, spec))
    c(MSC, HLR, package(QUERY_PERM, tid(), [invoke((1,), opcode_national(0x0102), tlv(UNI, True, 16, b''))]),
      'national opcode, parameter not a parameter set: no parameters')
    c(MSC, HLR, package(QUERY_PERM, tid(), [invoke((1,), opcode_national(0x0102), None)]),
      'national opcode, no parameter')
    # registered national opcodes: LNP query and response
    t = tid()
    c(MSC, HLR, package(QUERY_PERM, t, [invoke((1,), opcode_national(LNP_PI), LNP_PI_ARG)]),
      'LNP Provide Instruction Start (national 0x8301)')
    c(HLR, MSC, package(RESPONSE, t, [invoke((2, 1), opcode_national(LNP_CC), LNP_CC_ARG)]),
      'LNP Connection Control Connect (national 0x0401)')
    # private opcodes: AIN, other private families
    t = tid()
    c(MSC, HLR, package(QUERY_PERM, t, [invoke((1,), opcode_private(AIN_ACTIVITY_TEST), AIN_ACTIVITY_ARG)]),
      'AIN activityTest Invoke (private 0x6906)')
    c(HLR, MSC, package(RESPONSE, t, [return_result(1, AIN_ACTIVITY_RES)]),
      'AIN activityTest ReturnResult (matched, to AIN)')
    c(MSC, HLR, package(QUERY_PERM, tid(), [invoke((1,), opcode_private(0x0105), pset())]),
      'private opcode 0x0105: not implemented')
    c(MSC, HLR, package(QUERY_PERM, tid(), [invoke((1,), opcode_private(0x7001), pset())]),
      'private opcode 0x7001: not implemented')

    # ---- invoke/result matching
    t = tid()
    c(MSC, HLR, package(QUERY_PERM, t, [invoke((1,), opcode_national(0x0101), national_set(*NAT_PARAMS[:2]))]),
      'national Invoke MSC to HLR')
    c(HLR, MSC, package(RESPONSE, t, [return_result(1, national_set(NAT_PARAMS[17], NAT_PARAMS[18]))]),
      'ReturnResult HLR to MSC: matched with every matching type')
    t = tid()
    c(MSC, HLR, package(QUERY_PERM, t, [invoke((1,), opcode_national(0x0101), national_set(NAT_PARAMS[1]))]),
      'national Invoke MSC to HLR')
    c(RELAY, MSC, package(RESPONSE, t, [return_result(1, national_set(NAT_PARAMS[5]))]),
      'ReturnResult relay to MSC: matched by TID and by TID+source, not by TID+source+destination')
    t = tid()
    c(MSC, HLR, package(QUERY_PERM, t, [invoke((1,), opcode_national(0x0101), national_set(NAT_PARAMS[1]))]),
      'national Invoke MSC to HLR')
    c(HLR, MSCB, package(RESPONSE, t, [return_result(1, national_set(NAT_PARAMS[5]))]),
      'ReturnResult HLR to MSC-B: matched by TID only')
    t = tid()
    c(MSC, HLR, package(QUERY_PERM, t, [invoke((1,), opcode_national(0x0101), national_set(NAT_PARAMS[1]))]),
      'TID reused: first Invoke (national 0x0101)')
    c(MSC, HLR, package(QUERY_PERM, t, [sms()]), 'TID reused: second Invoke (ANSI MAP)')
    c(HLR, MSC, package(RESPONSE, t, [return_result(1, SMSDPP_RES)]), 'ReturnResult matched with the second Invoke')
    c(HLR, MSC, package(RESPONSE, tid(), [return_result(1, national_set(NAT_PARAMS[5]))]),
      'ReturnResult with an unknown TID: not matched (national opcode 0)')

    # ---- national parameters: every parameter_type() case
    for i in range(0, len(NAT_PARAMS), 8):
        c(MSC, HLR, package(QUERY_PERM, tid(), [invoke((1,), opcode_national(0x0101), national_set(*NAT_PARAMS[i:i + 8]))]),
          'national parameters %d-%d' % (i, min(i + 8, len(NAT_PARAMS)) - 1))
    c(MSC, HLR, package(QUERY_PERM, tid(), [invoke((1,), opcode_national(0x0101), national_set())]),
      'national parameter set, empty')

    # ---- reproducers of the branch fix
    rep = reproducers()
    # Check that the octets rebuilt here are the reproducers' octets
    for name, payloads in rep.items():
        path = os.path.join(repro_dir, 'ansi_tcap_%s.pcap' % name)
        if os.path.exists(path):
            assert read_exported_pdus(path) == payloads, name
    # The reproducers lack mandatory parameters (BER "missing field"
    # warnings, Malformed group) or use an unknown AIN operation; the main
    # capture has them with the same structure, TIDs and component counts
    # and valid parameters, the malformed capture has them unchanged.
    for name, n, op, arg in (('many_components', 600, opcode_private(SMSDPP), SMSDPP_ARG_NOBD),
                             ('many_components_ok', 400, opcode_private(SMSDPP), SMSDPP_ARG_NOBD),
                             ('many_components_ain', 600, opcode_private(AIN_ACTIVITY_TEST), AIN_ACTIVITY_ARG_SMALL),
                             ('many_components_lnp', 600, opcode_national(LNP_PI), LNP_PI_ARG)):
        t = bytes([0, 0, 0, {'many_components_ain': 2, 'many_components_lnp': 3}.get(name, 1)])
        comps = [invoke((i & 0xff,), op, arg, last=(i == n - 1)) for i in range(n)]
        c(MSC, HLR, package(QUERY_PERM, t, comps), 'reproducer %s, valid parameters' % name)
    comps = [invoke((1,), opcode_private(SMSDPP), SMSDPP_ARG, last=False),
             return_result(1, SMSDPP_RES, last=False),
             invoke((2,), opcode_private(REGNOT), REGNOT_ARG)]
    c(HLR, MSC, package(RESPONSE, b'\x00\x00\x00\x10', comps),
      'reproducer same_frame_match, valid parameters: Invoke, ReturnResult, Invoke in one package')
    for t in (bytes(range(8)), bytes(300), bytes(256), b'\x01\x02\x03'):
        c(MSC, HLR, package(QUERY_PERM, t, [sms()]), 'reproducer tid_lengths, %d-octet TID, valid parameters' % len(t))

    # ---------------------------------------------------- malformed capture
    for name in ('many_components', 'many_components_ok', 'many_components_ain', 'many_components_lnp',
                 'same_frame_match', 'tid_lengths', 'national_params'):
        for i, p in enumerate(rep[name]):
            m(MSC, HLR, p, 'reproducer %s %d, unchanged' % (name, i + 1))
    # Every parameter with a value cut short (the last octet missing)
    for p in NAT_PARAMS:
        if len(p) > 5:
            cut = p[:-2]
            m(MSC, HLR, package(QUERY_PERM, tid(), [invoke((1,), opcode_national(0x0101), national_set(cut))]),
              'national parameter 0x%02x cut short' % p[0])
    # Parameter set too short for the length octet / identifier
    m(MSC, HLR, package(QUERY_PERM, tid(), [invoke((1,), opcode_national(0x0101), b'\xf2\x01\x8a')]),
      'national parameter set of 1 octet')
    m(MSC, HLR, package(QUERY_PERM, tid(), [invoke((1,), opcode_national(0x0101), b'\xf2\x02\x7f\x21')]),
      'national 2-octet identifier without length')
    # BER problems: TID of the wrong class, truncated package, constraint
    # violations (component IDs of 3 octets, 2-octet version)
    m(MSC, HLR, tlv(PRI, True, QUERY_PERM, tlv(PRI, False, 7, b'\x01\x02') + b'\xe8\x10\xe9'),
      'truncated component sequence')
    m(MSC, HLR, package(QUERY_PERM, tid(), [invoke((1, 2, 3), opcode_private(SMSDPP), SMSDPP_ARG)]),
      'componentIDs of 3 octets')
    m(MSC, HLR, package(QUERY_PERM, tid(), [sms()], tlv(PRI, True, 25, tlv(PRI, False, 26, b'\x01\x02'))),
      'protocol version of 2 octets')
    m(HLR, MSC, package(RESPONSE, tid(), [reject((1, 2), 257, 16)]), 'Reject with a 2-octet component ID')
    m(HLR, MSC, tlv(PRI, True, ABORT, tlv(PRI, False, 7, b'\x01\x02\x03\x04')), 'abort without a cause')
    m(MSC, HLR, tlv(PRI, True, QUERY_PERM, tlv(PRI, False, 8, b'')), 'package without a TID')
    m(MSC, HLR, tlv(PRI, True, UNIDIR, tlv(PRI, False, 7, b'')), 'unidirectional without component portion')
    m(MSC, HLR, package(QUERY_PERM, tid(), [tlv(PRI, True, 15, b'\x01')]), 'unknown component type')
    m(MSC, HLR, package(QUERY_PERM, tid(), [invoke((1,), tlv(PRI, False, 30, b'\x01'), None)]), 'unknown operation code choice')
    m(HLR, MSC, package(RESPONSE, tid(), [return_error(1, tlv(PRI, False, 30, b'\x01'), None)]), 'unknown error code choice')
    m(HLR, MSC, package(RESPONSE, tid(), [tlv(PRI, True, 12, component_ids(1) + tlv(PRI, False, 21, b'\x01\x01') +
                                              tlv(PRI, True, 17, b''))]), 'Reject with an unknown parameter choice')
    m(HLR, MSC, abort(tid(), tlv(PRI, False, 25, b'')), 'abort with an unknown cause choice')
    return clean, malformed


def main():
    out = sys.argv[1] if len(sys.argv) > 1 else '.'
    clean, malformed = build(reproducer_dir(os.path.dirname(os.path.abspath(__file__)), ['ansi_tcap_gen.py']))
    write_frames(os.path.join(out, 'ansi_tcap-coverage.pcap'), clean)
    write_frames(os.path.join(out, 'ansi_tcap-coverage-malformed.pcap'), malformed)
    print('%d + %d frames' % (len(clean), len(malformed)), file=sys.stderr)


if __name__ == '__main__':
    main()
